unsafe extern "C" fn impl_from_IDirect3DVertexBuffer7(iface: *mut IDirect3DVertexBuffer7) -> *mut d3d_vertex_buffer {
    return CONTAINING_RECORD!(iface, d3d_vertex_buffer, IDirect3DVertexBuffer7_iface);
}

unsafe extern "system" fn d3d_vertex_buffer7_QueryInterface(iface: *mut IDirect3DVertexBuffer7, riid: REFIID, obj: *mut *mut core::ffi::c_void) -> HRESULT {
    let buffer: *mut d3d_vertex_buffer = impl_from_IDirect3DVertexBuffer7(iface);

    *obj = core::ptr::null_mut();

    if IsEqualGUID!(core::ptr::addr_of!(IID_IUnknown), riid) != false {
        IDirect3DVertexBuffer7_AddRef(iface);
        *obj = iface as *mut core::ffi::c_void;
        return S_OK;
    }
    if IsEqualGUID!(core::ptr::addr_of!(IID_IDirect3DVertexBuffer7), riid) != false && (*buffer).version == 7 {
        IDirect3DVertexBuffer7_AddRef(iface);
        *obj = iface as *mut core::ffi::c_void;
        return S_OK;
    }
    if IsEqualGUID!(core::ptr::addr_of!(IID_IDirect3DVertexBuffer), riid) != false && (*buffer).version == 3 {
        IDirect3DVertexBuffer7_AddRef(iface);
        *obj = iface as *mut core::ffi::c_void;
        return S_OK;
    }

    WARN!("%s not implemented, returning E_NOINTERFACE.\n", debugstr_guid(riid));
    return E_NOINTERFACE;
}
unsafe extern "system" fn d3d_vertex_buffer7_AddRef(mut iface: *mut IDirect3DVertexBuffer7) -> ULONG {
    let mut buffer: *mut d3d_vertex_buffer = impl_from_IDirect3DVertexBuffer7(iface);
    let mut ref_0: ULONG = InterlockedIncrement(
        core::ptr::addr_of_mut!((*buffer).ref_) as *mut ::core::ffi::c_long,
    ) as ULONG;

    return ref_0;
}

unsafe extern "system" fn d3d_vertex_buffer7_Release(iface: *mut IDirect3DVertexBuffer7) -> ULONG {
    let buffer: *mut d3d_vertex_buffer = impl_from_IDirect3DVertexBuffer7(iface);
    let ref_0: ULONG = InterlockedDecrement(
        &raw mut (*buffer).ref_ as *mut ::core::ffi::c_long,
    ) as ULONG;
    let mut device: *mut d3d_device = core::ptr::null_mut();

    if ref_0 == 0 {
        /* D3D7 vertex buffers don't stay bound in the device, they are passed
         * as a parameter to DrawPrimitiveVB. DrawPrimitiveVB sets them as the
         * stream source in wined3d and they should get unset there before
         * they are destroyed. */
        wined3d_mutex_lock();

        device = ((*(*buffer).ddraw).d3ddevice_list.next as *mut u8).offset(
            -(core::mem::offset_of!(d3d_device, ddraw_entry) as isize),
        ) as *mut d3d_device;
        while &raw mut (*device).ddraw_entry != &raw mut (*(*buffer).ddraw).d3ddevice_list {
            if (*(*device).stateblock_state).streams[0 as usize].buffer
                == (*buffer).wined3d_buffer
            {
                wined3d_stateblock_set_stream_source(
                    (*device).state,
                    0,
                    core::ptr::null_mut(),
                    0,
                    0,
                );
            }
            device = ((*device).ddraw_entry.next as *mut u8).offset(
                -(core::mem::offset_of!(d3d_device, ddraw_entry) as isize),
            ) as *mut d3d_device;
        }

        wined3d_vertex_declaration_decref((*buffer).wined3d_declaration);
        wined3d_buffer_decref((*buffer).wined3d_buffer);
        wined3d_mutex_unlock();

        if (*buffer).version == 7 {
            IDirectDraw7_Release(&raw mut (*(*buffer).ddraw).IDirectDraw7_iface);
        }

        free(buffer as *mut core::ffi::c_void);
    }

    ref_0
}

unsafe extern "C" fn d3d_vertex_buffer_create_wined3d_buffer(
    buffer: *mut d3d_vertex_buffer,
    dynamic: BOOL,
    wined3d_buffer: *mut *mut wined3d_buffer,
) -> HRESULT {
    let mut desc: wined3d_buffer_desc = core::mem::zeroed();

    desc.byte_width = (*buffer).size;
    desc.usage = WINED3DUSAGE_STATICDECL | WINED3DUSAGE_VIDMEM_ACCOUNTING;
    if dynamic != 0 {
        desc.usage |= WINED3DUSAGE_DYNAMIC;
    }
    desc.bind_flags = WINED3D_BIND_VERTEX_BUFFER;
    if (*buffer).sysmem {
        desc.access = WINED3D_RESOURCE_ACCESS_CPU | WINED3D_RESOURCE_ACCESS_MAP_R | WINED3D_RESOURCE_ACCESS_MAP_W;
    } else {
        desc.access = WINED3D_RESOURCE_ACCESS_GPU | WINED3D_RESOURCE_ACCESS_MAP_R | WINED3D_RESOURCE_ACCESS_MAP_W;
    }
    desc.misc_flags = 0;
    desc.structure_byte_stride = 0;

    return wined3d_buffer_create(
        (*(*buffer).ddraw).wined3d_device,
        core::ptr::addr_of_mut!(desc),
        core::ptr::null(),
        buffer as *mut core::ffi::c_void,
        core::ptr::addr_of!(ddraw_null_wined3d_parent_ops),
        wined3d_buffer,
    );
}

unsafe extern "system" fn d3d_vertex_buffer7_Lock(
    iface: *mut IDirect3DVertexBuffer7,
    mut flags: DWORD,
    data: *mut *mut core::ffi::c_void,
    data_size: *mut DWORD,
) -> HRESULT {
    let buffer: *mut d3d_vertex_buffer = impl_from_IDirect3DVertexBuffer7(iface);
    let mut wined3d_desc: wined3d_resource_desc = core::mem::zeroed();
    let mut wined3d_resource: *mut wined3d_resource = core::ptr::null_mut();
    let mut wined3d_map_desc: wined3d_map_desc = core::mem::zeroed();
    let mut hr: HRESULT = 0;

    if (*buffer).version != 7 {
        flags &= !(DDLOCK_NOOVERWRITE | DDLOCK_DISCARDCONTENTS);
    }

    if (*buffer).discarded {
        flags &= !DDLOCK_DISCARDCONTENTS;
    }

    if !((flags & DDLOCK_WAIT) != 0) {
        flags |= DDLOCK_DONOTWAIT;
    }
    if (flags & DDLOCK_DISCARDCONTENTS) != 0 {
        (*buffer).discarded = true;
        if (*buffer).dynamic == 0 {
            let mut new_buffer: *mut wined3d_buffer = core::ptr::null_mut();
            wined3d_mutex_lock();
            hr = d3d_vertex_buffer_create_wined3d_buffer(
                buffer,
                (TRUE) as BOOL,
                core::ptr::addr_of_mut!(new_buffer),
            );
            if hr >= 0 {
                (*buffer).dynamic = (TRUE as i32);
                wined3d_buffer_decref((*buffer).wined3d_buffer);
                (*buffer).wined3d_buffer = new_buffer;
            } else {
                WARN!("Failed to create a dynamic buffer\n");
            }
            wined3d_mutex_unlock();
        }
    }

    wined3d_mutex_lock();
    if !data_size.is_null() {
        /* Get the size, for returning it, and for locking */
        wined3d_resource = wined3d_buffer_get_resource((*buffer).wined3d_buffer);
        wined3d_resource_get_desc(wined3d_resource, core::ptr::addr_of_mut!(wined3d_desc));
        *data_size = wined3d_desc.size as DWORD;
    }

    hr = wined3d_resource_map(
        wined3d_buffer_get_resource((*buffer).wined3d_buffer),
        0,
        core::ptr::addr_of_mut!(wined3d_map_desc),
        core::ptr::null(),
        wined3dmapflags_from_ddrawmapflags(flags),
    );
    *data = wined3d_map_desc.data;

    wined3d_mutex_unlock();

    return hr;
}

unsafe extern "system" fn d3d_vertex_buffer7_Unlock(iface: *mut IDirect3DVertexBuffer7) -> HRESULT {
    let buffer: *mut d3d_vertex_buffer = impl_from_IDirect3DVertexBuffer7(iface);

    wined3d_resource_unmap(wined3d_buffer_get_resource((*buffer).wined3d_buffer), 0);
    return D3D_OK;
}

unsafe extern "system" fn d3d_vertex_buffer7_ProcessVertices(
    iface: *mut IDirect3DVertexBuffer7,
    vertex_op: DWORD,
    dst_idx: DWORD,
    count: DWORD,
    src_buffer: *mut IDirect3DVertexBuffer7,
    src_idx: DWORD,
    device: *mut IDirect3DDevice7,
    flags: DWORD,
) -> HRESULT {
    let dst_buffer_impl: *mut d3d_vertex_buffer = impl_from_IDirect3DVertexBuffer7(iface);
    let src_buffer_impl: *mut d3d_vertex_buffer = unsafe_impl_from_IDirect3DVertexBuffer7(src_buffer);
    let device_impl: *mut d3d_device = if (*dst_buffer_impl).version == 7 as DWORD {
        unsafe_impl_from_IDirect3DDevice7(device)
    } else {
        unsafe_impl_from_IDirect3DDevice3(device as *mut IDirect3DDevice3)
    };
    let mut old_clip: BOOL;
    let mut do_clip: BOOL;
    let mut old_lighting: BOOL;
    let mut do_lighting: BOOL;
    let mut state: *const wined3d_stateblock_state;
    let mut hr: HRESULT;

    WINE_TRACE!("iface %p, vertex_op %#lx, dst_idx %lu, count %lu, src_buffer %p, src_idx %lu, device %p, flags %#lx.\n", iface, vertex_op, dst_idx, count, src_buffer, src_idx, device, flags);

    /* Vertex operations:
     * D3DVOP_CLIP: Clips vertices outside the viewing frustrum. Needs clipping information
     * in the vertex buffer (Buffer may not be created with D3DVBCAPS_DONOTCLIP)
     * D3DVOP_EXTENTS: Causes the screen extents to be updated when rendering the vertices
     * D3DVOP_LIGHT: Lights the vertices
     * D3DVOP_TRANSFORM: Transform the vertices. This flag is necessary
     *
     * WineD3D only transforms and clips the vertices by now, so EXTENTS and LIGHT
     * are not implemented. Clipping is disabled ATM, because of unsure conditions.
     */
    if vertex_op & (D3DVOP_TRANSFORM as DWORD) == 0 {
        return DDERR_INVALIDPARAMS as HRESULT;
    }

    wined3d_mutex_lock();

    state = (*device_impl).stateblock_state;

    /* WineD3D doesn't know d3d7 vertex operation, it uses
     * render states instead. Set the render states according to
     * the vertex ops
     */
    do_clip = (vertex_op & (D3DVOP_CLIP as DWORD) != 0) as ::core::ffi::c_int as BOOL;
    old_clip = ((*state).rs[WINED3D_RS_CLIPPING as usize] != 0) as ::core::ffi::c_int as BOOL;
    if do_clip != old_clip {
        wined3d_stateblock_set_render_state(
            (*device_impl).state,
            WINED3D_RS_CLIPPING,
            do_clip as ::core::ffi::c_uint,
        );
    }

    old_lighting = ((*state).rs[WINED3D_RS_LIGHTING as usize] != 0) as ::core::ffi::c_int as BOOL;
    if (*dst_buffer_impl).version == 3 as DWORD {
        do_lighting = ((*device_impl).material != 0
            && (*src_buffer_impl).fvf & (D3DFVF_NORMAL as DWORD) != 0
            && vertex_op & (D3DVOP_LIGHT as DWORD) != 0) as ::core::ffi::c_int
            as BOOL;
    } else {
        do_lighting = (old_lighting != 0
            && vertex_op & (D3DVOP_LIGHT as DWORD) != 0) as ::core::ffi::c_int
            as BOOL;
    }

    if do_lighting != old_lighting {
        wined3d_stateblock_set_render_state(
            (*device_impl).state,
            WINED3D_RS_LIGHTING,
            do_lighting as ::core::ffi::c_uint,
        );
    }

    wined3d_stateblock_set_stream_source(
        (*device_impl).state,
        0,
        (*src_buffer_impl).wined3d_buffer,
        0,
        get_flexible_vertex_size((*src_buffer_impl).fvf) as UINT,
    );
    wined3d_stateblock_set_vertex_declaration((*device_impl).state, (*src_buffer_impl).wined3d_declaration);
    hr = wined3d_device_process_vertices(
        (*device_impl).wined3d_device,
        (*device_impl).state,
        src_idx as UINT,
        dst_idx as UINT,
        count as UINT,
        (*dst_buffer_impl).wined3d_buffer,
        core::ptr::null_mut(),
        flags as uint32_t,
        (*dst_buffer_impl).fvf as uint32_t,
    );

    /* Restore the states if needed */
    if do_clip != old_clip {
        wined3d_stateblock_set_render_state(
            (*device_impl).state,
            WINED3D_RS_CLIPPING,
            old_clip as ::core::ffi::c_uint,
        );
    }
    if do_lighting != old_lighting {
        wined3d_stateblock_set_render_state(
            (*device_impl).state,
            WINED3D_RS_LIGHTING,
            old_lighting as ::core::ffi::c_uint,
        );
    }

    wined3d_mutex_unlock();

    return hr;
}

unsafe extern "system" fn d3d_vertex_buffer7_GetVertexBufferDesc(iface: *mut IDirect3DVertexBuffer7, desc: *mut D3DVERTEXBUFFERDESC) -> HRESULT {
    let mut buffer: *mut d3d_vertex_buffer = impl_from_IDirect3DVertexBuffer7(iface);
    let mut wined3d_desc: wined3d_resource_desc = core::mem::zeroed();
    let mut wined3d_resource: *mut wined3d_resource = core::ptr::null_mut();

    if desc.is_null() {
        return DDERR_INVALIDPARAMS;
    }

    wined3d_mutex_lock();
    wined3d_resource = wined3d_buffer_get_resource((*buffer).wined3d_buffer);
    wined3d_resource_get_desc(wined3d_resource, core::ptr::addr_of_mut!(wined3d_desc));
    wined3d_mutex_unlock();

    /* Now fill the desc structure */
    (*desc).dwCaps = (*buffer).Caps;
    (*desc).dwFVF = (*buffer).fvf;
    (*desc).dwNumVertices = (wined3d_desc.size as DWORD) / get_flexible_vertex_size((*buffer).fvf);

    return D3D_OK;
}

unsafe extern "system" fn d3d_vertex_buffer7_Optimize(iface: *mut IDirect3DVertexBuffer7, device: *mut IDirect3DDevice7, flags: DWORD) -> HRESULT {
    let buffer: *mut d3d_vertex_buffer = impl_from_IDirect3DVertexBuffer7(iface);
    static mut hide: BOOL = (FALSE as i32);

    TRACE!("iface %p, device %p, flags %#lx.\n", iface, device, flags);

    if hide == 0 {
        FIXME!("iface %p, device %p, flags %#lx stub!\n", iface, device, flags);
        hide = (TRUE as i32);
    }

    /* We could forward this call to WineD3D and take advantage
     * of it once we use OpenGL vertex buffers
     */
    wined3d_mutex_lock();
    (*buffer).Caps |= D3DVBCAPS_OPTIMIZED;
    wined3d_mutex_unlock();

    return DD_OK;
}
