#[no_mangle]
pub unsafe extern "C" fn d3d_vertex_buffer_create(
    vertex_buf: *mut *mut d3d_vertex_buffer,
    ddraw: *mut ddraw,
    desc: *mut D3DVERTEXBUFFERDESC,
) -> HRESULT {
    let mut buffer: *mut d3d_vertex_buffer = core::ptr::null_mut();
    let mut hr: HRESULT = D3D_OK;

    buffer = calloc(
        1,
        (core::mem::size_of::<d3d_vertex_buffer>()) as _,
    ) as *mut d3d_vertex_buffer;
    if buffer.is_null() {
        return DDERR_OUTOFMEMORY;
    }

    (*buffer).IDirect3DVertexBuffer7_iface.lpVtbl =
        &raw const d3d_vertex_buffer7_vtbl as *const IDirect3DVertexBuffer7Vtbl;
    (*buffer).ref_ = 1 as LONG;
    (*buffer).version = (*ddraw).d3dversion as core::ffi::c_uint;
    if (*buffer).version == 7 {
        IDirectDraw7_AddRef(&raw mut (*ddraw).IDirectDraw7_iface);
    }
    (*buffer).ddraw = ddraw;
    (*buffer).Caps = (*desc).dwCaps;
    (*buffer).fvf = (*desc).dwFVF;
    (*buffer).size = get_flexible_vertex_size((*desc).dwFVF).wrapping_mul((*desc).dwNumVertices);

    /* ddraw4 vertex buffers ignore DISCARD and NOOVERWRITE, even on
     * pretransformed geometry, which means that a GPU-based buffer cannot
     * perform well.
     *
     * While at least one contemporaneous card (Geforce 4) does seem to show a
     * difference in its performance characteristics based on whether
     * D3DVBCAPS_SYSTEMMEMORY is set, it also doesn't *improve* performance to
     * use a non-SYSTEMMEMORY buffer with ddraw4. For wined3d it should always
     * be better to use sysmem.
     *
     * This improves performance in Prince of Persia 3D. */
    (*buffer).sysmem = (((*buffer).Caps as core::ffi::c_ulong
        & D3DVBCAPS_SYSTEMMEMORY as core::ffi::c_ulong)
        != 0
        || (*buffer).version < 7);

    wined3d_mutex_lock();

    hr = d3d_vertex_buffer_create_wined3d_buffer(
        buffer,
        (FALSE) as BOOL,
        &raw mut (*buffer).wined3d_buffer,
    );
    'end: {
        if hr < 0 {
            WARN!(
                "Failed to create wined3d vertex buffer, hr %#lx.\n",
                hr
            );
            if hr == WINED3DERR_INVALIDCALL {
                hr = DDERR_INVALIDPARAMS;
            }
            break 'end;
        }

        (*buffer).wined3d_declaration = ddraw_find_decl(ddraw, (*desc).dwFVF);
        if (*buffer).wined3d_declaration.is_null() {
            ERR!(
                "Failed to find vertex declaration for fvf %#lx.\n",
                (*desc).dwFVF
            );
            wined3d_buffer_decref((*buffer).wined3d_buffer);
            hr = DDERR_INVALIDPARAMS;
            break 'end;
        }
        wined3d_vertex_declaration_incref((*buffer).wined3d_declaration);
    }

    wined3d_mutex_unlock();
    if hr == D3D_OK {
        *vertex_buf = buffer;
    } else {
        free(buffer as *mut core::ffi::c_void);
    }

    return hr;
}
#[no_mangle]
pub unsafe extern "C" fn unsafe_impl_from_IDirect3DVertexBuffer7(
    iface: *mut IDirect3DVertexBuffer7,
) -> *mut d3d_vertex_buffer {
    if iface.is_null() {
        return core::ptr::null_mut();
    }
    assert!((*iface).lpVtbl as *const _ == &raw const d3d_vertex_buffer7_vtbl);

    return impl_from_IDirect3DVertexBuffer7(iface);
}

